// Template registry (Day 16) — pure and client-safe.
//
// A template is a real DOCX file with real, original content
// (Forma's own — no WPS template, no copied text), committed in
// src/lib/templates/ and generated by scripts/generate-templates.py
// (the script is the source of truth; it also renders the first-page
// thumbnail into public/templates/ and extracts the preview text
// into <slug>.preview.json, so the preview can never drift from
// the file).
//
// This module only lists the templates and their preview data, so
// the gallery page can import it. The DOCX bytes are read by
// src/lib/templates.server.ts (which uses node:fs and must never
// be imported by a client component).
import resumePreview from "@/lib/templates/resume.preview.json";
import letterPreview from "@/lib/templates/letter.preview.json";
import reportPreview from "@/lib/templates/report.preview.json";

export type TemplatePreviewEntry = {
  style: string;
  text: string;
};

export type Template = {
  id: string;
  name: string;
  description: string;
  category: string;
  fileName: string;
  thumbnailPath: string;
  preview: TemplatePreviewEntry[];
};

export const TEMPLATES: Template[] = [
  {
    id: "resume",
    name: "Professional Resume",
    description:
      "A one-page resume — summary, experience, education and skills. Replace the bracketed placeholders with your details.",
    category: "Career",
    fileName: "resume.docx",
    thumbnailPath: "/templates/resume.png",
    preview: resumePreview as TemplatePreviewEntry[],
  },
  {
    id: "letter",
    name: "Formal Business Letter",
    description:
      "A formal letter — sender and recipient addresses, subject, body and closing. Replace the bracketed placeholders with your details.",
    category: "Business",
    fileName: "letter.docx",
    thumbnailPath: "/templates/letter.png",
    preview: letterPreview as TemplatePreviewEntry[],
  },
  {
    id: "report",
    name: "Business Report",
    description:
      "A structured report — executive summary, findings, a results table, conclusion and recommendations. Replace the bracketed placeholders with your content.",
    category: "Business",
    fileName: "report.docx",
    thumbnailPath: "/templates/report.png",
    preview: reportPreview as TemplatePreviewEntry[],
  },
];

export type TemplateId = (typeof TEMPLATES)[number]["id"];

export function isTemplateId(id: string): id is TemplateId {
  return TEMPLATES.some((t) => t.id === id);
}

export function getTemplate(id: TemplateId): Template {
  return TEMPLATES.find((t) => t.id === id) as Template;
}
